    /*
     * Assign a PayrollCalendar
     * 
     * @param	parentId	UUID
     * @param	assignment 	PayrollCalendar 
     * @return	PayrollRun
     */
    public PayrollRun assignPayrollCalendar( UUID parentId, PayrollCalendar assignment ) {
	    LOGGER.info("assigning PayrollCalendar as " + assignment.toString() );

	    PayrollRun parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( PayrollCalendar.class, assignment.getPayrollCalendarId());

	    // ------------------------------------------
		// assign the PayrollCalendar to the parent entity
		// ------------------------------------------ 
	    parentEntity.setPayrollCalendar( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the PayrollCalendar
	 * 
	 * @param	parentId		UUID
	 * @return	PayrollRun
	 */
	public PayrollRun unAssignPayrollCalendar( UUID parentId ) {
		PayrollRun parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning PayrollCalendar on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the PayrollCalendar on the parent entithy
		// ------------------------------------------     
	    parentEntity.setPayrollCalendar(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}


    /*
     * Add to the PayrollItems
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	PayrollRun
     */
    public PayrollRun addToPayrollItems( UUID parentId, PayrollItem addTo ) {
	    LOGGER.info("handling AssignPayrollItemsToPayrollRunEvent - " );
	    
	    PayrollRun parentEntity = repository.findById(parentId).get();
	    PayrollItem child = registry.project( PayrollItem.class, addTo.getPayrollItemId());
	    
	    parentEntity.getPayrollItems().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the PayrollItems
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	PayrollRun
     */
	public PayrollRun removeFromPayrollItems( UUID parentId, PayrollItem removeFrom ) {
	    LOGGER.info("handling RemovePayrollItemsFromPayrollRunEvent " );
	
	    PayrollRun parentEntity = repository.findById(parentId).get();
	    PayrollItem child = registry.project( PayrollItem.class, removeFrom.getPayrollItemId());
	    
	    parentEntity.getPayrollItems().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



